// syncResource handles the full paginated sync of a single resource.
// It resumes from the last cursor unless sinceTS or full mode overrides it.
// channel_workflow.go.tmpl mirrors the trailing dates arg conditional;
// keep both call sites in sync if this signature changes.
func syncResource(ctx context.Context, c interface {
	Get(context.Context, string, map[string]string) (json.RawMessage, error)
	RateLimit() float64
}, db *store.Store, resource, sinceTS string, full bool, maxPages int, latestOnly bool, userParams *syncUserParams, syncEvents io.Writer) syncResult {
	started := time.Now()
	if syncEvents == nil {
		syncEvents = io.Discard
	}
	// PATCH(pagination-headers): collect the Fiken-Api-* headers of this walk's
	// first page, the only statement Fiken makes about how many rows the
	// collection holds (issue #15). c.Get keeps its signature; the sink rides
	// the context.
	ctx, pageSink := client.NewPageInfoContext(ctx)

	if !humanFriendly {
		fmt.Fprintf(syncEvents, `{"event":"sync_start","resource":"%s"}`+"\n", resource)
	}

	path, err := syncResourcePath(resource)
	if err != nil {
		// PATCH(sync-named-dependents): the one error path that returned
		// without emitting an event, so a machine-mode consumer saw an
		// anonymous failure in the summary and nothing else (issue #14). A
		// name that is neither flat nor dependent reaches here; say which.
		if !humanFriendly {
			fmt.Fprintln(syncEvents, syncErrorJSON(resource, "", err))
		}
		return syncResult{Resource: resource, Err: err, Duration: time.Since(started)}
	}

	// Skip resources whose path template still contains unresolved `{key}`
	// placeholders after syncResourcePath() resolution. These paths require
	// parent context (league_key, team_key, channel_id, etc.) that flat-list
	// sync cannot fill. Emit a sync_warning describing the missing keys and
	// continue — sync exits 0 if any resource succeeded, so this keeps
	// hierarchical-API CLIs functional for the resources they CAN sync flat.
	if missingKeys := unresolvedPathKeyRE.FindAllString(path, -1); len(missingKeys) > 0 {
		if !humanFriendly {
			payload := struct {
				Event    string   `json:"event"`
				Resource string   `json:"resource"`
				Reason   string   `json:"reason"`
				Keys     []string `json:"keys"`
				Path     string   `json:"path"`
				Message  string   `json:"message"`
			}{
				Event:    "sync_warning",
				Resource: resource,
				Reason:   "unfilled_path_key",
				Keys:     missingKeys,
				Path:     path,
				Message:  fmt.Sprintf("path %s requires parent context (%s); resource skipped", path, strings.Join(missingKeys, ", ")),
			}
			payloadJSON, _ := json.Marshal(payload)
			fmt.Fprintf(syncEvents, "%s\n", payloadJSON)
		} else {
			fmt.Fprintf(os.Stderr, "  %s skipped (requires parent context: %s)\n",
				resource, strings.Join(missingKeys, ", "))
		}
		return syncResult{
			Resource: resource,
			Warn:     fmt.Errorf("skipped %s: unresolved path keys %v", resource, missingKeys),
			Duration: time.Since(started),
		}
	}

	var totalCount int

	// Resume cursor from sync_state (unless --full cleared it)
	existingCursor, lastSynced, _, _ := db.GetSyncState(resource)
	if !full {
		if storedCount, err := db.Count(resource); err == nil && storedCount == 0 {
			existingCursor = ""
			lastSynced = time.Time{}
		}
	}

	// Determine the since param value:
	// 1. Explicit --since flag takes priority
	// 2. Otherwise use last_synced_at from sync_state for incremental sync
	// PATCH(pagination-headers): the seam issue #13 fills; today it delegates
	// to the generated (empty) mapping.
	sinceParam := syncSinceParamFor(resource)
	effectiveSince := sinceTS
	if effectiveSince == "" && !lastSynced.IsZero() && !full {
		effectiveSince = lastSynced.Format(time.RFC3339)
	}
	// Resources whose list endpoint declares no temporal-filter parameter
	// fall back to plain pagination — sending a synthetic since=... would
	// reach the API as an unknown query param and (for strict APIs like
	// Notion) fail the whole resource with a 400. Warn once per resource
	// when the user expected incremental behavior.
	if effectiveSince != "" && sinceParam == "" {
		if humanFriendly {
			fmt.Fprintf(os.Stderr, "  %s: incremental sync ignored (endpoint declares no temporal filter; falling back to full pagination)\n", resource)
		} else {
			fmt.Fprintf(syncEvents, `{"event":"sync_warning","resource":"%s","reason":"resource_not_incremental","message":"endpoint does not declare a temporal filter parameter; incremental sync has no effect for this resource"}`+"\n", resource)
		}
		effectiveSince = ""
	}
	if effectiveSince != "" {
		// PATCH(sync-since-last-modified): floored to the day and stepped back
		// one, because lastModifiedGe is inclusive and lastModifiedDate is
		// day-granular with no zone (issue #13). This is the one formatting
		// site for both the --since flag and the watermark above.
		//
		// The sync_state.last_synced_at arm above is INERT for every shipped
		// resource, and saying so here beats implying otherwise: syncResource
		// walks flat resources, and `companies` is the only one, so sinceParam
		// is always "" here and it is dropped by the resource_not_incremental
		// branch above.
		// PATCH(sync-watermark): the default run IS incremental now, but not
		// through this arm — the watermark that windows it is the per-(company,
		// resource) row the dependent walker reads, not sync_state, which is
		// keyed by resource_type alone and stays exactly as `doctor` expects it
		// (issue #22).
		effectiveSince = syncSinceWindowValue(effectiveSince, syncSinceParamFormatFor(resource))
	}

	cursor := existingCursor
	// PATCH(pagination-headers): a walk that resumes from a stored cursor lands
	// only the tail of the collection, so its row count is not comparable with
	// Fiken-Api-Result-Count; the same applies to every early exit below
	// (issue #15). Only an uncapped walk over a whole collection is compared.
	walkTruncated := cursor != ""
	// PATCH(pagination-headers): a pull that asks for a subset of the collection
	// gets that subset's Result-Count back, which must not overwrite the
	// full-collection number recorded beside sync_state.total_count (issue #15).
	// Computed from the same inputs userParams.applyTo injects below, so a
	// --param / --resource-param filter counts as a window too.
	// PATCH(sync-since-last-modified): kept as one value for the whole walk,
	// not a bare flag, because issue #17's deletion pass must read the same
	// decision (syncPullWindow.AllowsDeletion).
	windowedPull := newSyncPullWindow(sinceParam, effectiveSince, userParams, resource, false)
	// PATCH(pagination-headers): distinct storage keys landed, which is what
	// "rows" has to mean when it is compared with Result-Count.
	landed := newLandedIDs()
	pageSize := determinePaginationDefaults()
	var progressCount int64
	pagesFetched := 0
	lastNextCursor := ""
	capExitHit := false
	capExitCursor := ""
	// extractFailureTotal accumulates per-item primary-key extraction
	// misses across pages within this resource sync. Resource-level
	// concurrency is 1 (one goroutine per resource via the work channel)
	// so this counter cannot race. We emit one primary_key_unresolved
	// sync_anomaly per resource per run when there's at least one miss
	// (rate-limited via the anomalyEmitted flag) and a roll-up
	// all_items_failed_id_extraction event when 100% of a single page
	// failed extraction.
	var extractFailureTotal int
	var consumedTotal int
	anomalyEmitted := false

	for {
		params := map[string]string{}

		if resourceSupportsPagination(resource) {
			params[pageSize.limitParam] = strconv.Itoa(pageSize.limit)
			if cursor != "" {
				params[pageSize.cursorParam] = cursor
			}
		}

		// Set since filter
		// PATCH(sync-since-last-modified): from the walk's window value, so the
		// parameter that goes on the wire and the windowedness the completeness
		// check and issue #17 read are the same fact.
		if windowedPull.Value != "" {
			params[windowedPull.Param] = windowedPull.Value
		}
		// Apply user-supplied --param / --resource-param overrides last so they
		// win over spec-derived defaults (e.g. forcing mine=true on a list
		// endpoint whose OpenAPI spec marks the filter optional).
		userParams.applyTo(resource, params, false)

		data, err := c.Get(ctx, path, params)
		if err != nil {
			if w, ok := isSyncAccessWarning(err); ok {
				if !humanFriendly {
					fmt.Fprintln(syncEvents, syncWarningJSON(resource, "", w.Status, w.Reason, w.Message))
				}
				return syncResult{Resource: resource, Count: totalCount, Warn: fmt.Errorf("skipped %s: %s", resource, w.Reason), Duration: time.Since(started)}
			}
			if !humanFriendly {
				fmt.Fprintln(syncEvents, syncErrorJSON(resource, "", err))
			}
			return syncResult{Resource: resource, Count: totalCount, Err: fmt.Errorf("fetching %s: %w", resource, err), Duration: time.Since(started)}
		}

		// Dry-run sentinel: client.dryRun returns `{"dry_run": true}` instead
		// of a real response when --dry-run is set. The upsert path below
		// would otherwise fail with "missing id for <resource>" because the
		// sentinel has no items and no id; emit a synthetic success event so
		// validate-narrative --full-examples (which auto-appends --dry-run)
		// sees a clean exit.
		if isDryRunResponse(data) {
			if !humanFriendly {
				fmt.Fprintf(syncEvents, `{"event":"sync_dryrun","resource":"%s"}`+"\n", resource)
			}
			return syncResult{Resource: resource, Count: 0, Duration: time.Since(started)}
		}

		// Try to extract items from the response.
		// Strategy: try array first, then common wrapper keys.
		items, nextCursor, hasMore := extractPageItems(data, pageSize.cursorParam)

		// Page-int paginator fallback: when the API paginates by integer
		// ?page=N and emits no body cursor, treat a full page as a signal
		// to advance numerically. Without this the loop breaks after page
		// 1 even though more pages exist (the original symptom in #1296).
		// Guard on cursorType, not cursorParam name, so all canonical
		// spellings (page / page_number / pageNumber / page[number]) work.
		// PATCH(pagination-zero-based): the first request omits the cursor, so
		// the server served pageSize.firstPage (the spec's default for the page
		// parameter, 0 here). Atoi("") clamped to 1 and asked for page 2 next,
		// so page 1 was never fetched (issue #12). Empty cursor means firstPage;
		// the next page is current+1, and a short page ends the loop below.
		if pageSize.cursorType == "page" && nextCursor == "" && len(items) >= pageSize.limit && pageAllowsPageIntFallback(data) {
			currentPage := pageSize.firstPage
			if n, err := strconv.Atoi(cursor); err == nil {
				currentPage = n
			}
			nextCursor = strconv.Itoa(currentPage + 1)
			hasMore = true
		}
		if pageSize.cursorType == "offset" && nextCursor == "" && len(items) >= pageSize.limit && pageAllowsPageIntFallback(data) {
			currentOffset, _ := strconv.Atoi(cursor)
			nextCursor = strconv.Itoa(currentOffset + pageSize.limit)
			hasMore = true
		}

		if len(items) == 0 && len(data) > 0 && !isJSONResponse(data) {
			if humanFriendly {
				fmt.Fprintf(os.Stderr, "\nwarning: %s returned a 200 response with a non-JSON body; no rows were stored.\n", resource)
			} else {
				fmt.Fprintf(syncEvents, `{"event":"sync_anomaly","resource":"%s","reason":"non_json_200_body"}`+"\n", resource)
			}
			walkTruncated = true // PATCH(pagination-headers)
			break
		}

		if len(items) == 0 {
			if isEmptyPageResponse(data) {
				break
			}
			// Single object response - try to store as-is
			if err := upsertSingleObject(db, resource, data); err != nil {
				if !humanFriendly {
					fmt.Fprintln(syncEvents, syncErrorJSON(resource, "", err))
				}
				return syncResult{Resource: resource, Err: err, Duration: time.Since(started)}
			}
			// PATCH(pagination-headers): a single-object body does not go through
			// UpsertBatch, so store.StorageKeyOf cannot say what it landed under
			// (a non-object body lands under the resource name with no key at
			// all). The walk has no comparable row count, so neither the
			// mismatch check nor the recorded value may use it (issue #15).
			walkTruncated = true
			totalCount++
			break
		}

		// Batch upsert all items from this page. UpsertBatch returns
		// (stored, extractFailures, err): stored counts rows actually
		// landed; extractFailures counts items that survived JSON
		// unmarshal but had no extractable primary key (templated
		// IDField AND generic fallback both missed). Tracking these
		// separately lets us emit precise sync_anomaly events: a
		// roll-up "all_items_failed_id_extraction" when an entire
		// page yields zero stored, a per-resource
		// "primary_key_unresolved" the first time any single item
		// fails, and the F4b "stored_count_zero_after_extraction"
		// probe when extraction succeeded but rows still didn't land.
		stored, extractFailures, err := upsertResourceBatch(db, resource, items)
		if err != nil {
			if !humanFriendly {
				fmt.Fprintln(syncEvents, syncErrorJSON(resource, "", err))
			}
			return syncResult{Resource: resource, Count: totalCount, Err: fmt.Errorf("upserting batch for %s: %w", resource, err), Duration: time.Since(started)}
		}

		landed.addBatch(resource, items) // PATCH(pagination-headers)
		consumedTotal += len(items)
		extractFailureTotal += extractFailures

		// When a non-empty page yielded zero stored rows, the API
		// returned items in a shape we couldn't extract IDs from —
		// likely scalar IDs (Firebase /topstories.json, GitHub user-
		// repo lists) where the spec author should declare a hydration
		// pattern, or an unrecognized primary-key field name.
		if len(items) > 0 && stored == 0 {
			if humanFriendly {
				fmt.Fprintf(os.Stderr, "warning: %s returned %d items but stored 0 — the local store will be empty for this resource. Likely cause: scalar item shape rather than objects with extractable IDs.\n", resource, len(items))
			} else {
				fmt.Fprintf(syncEvents, `{"event":"sync_anomaly","resource":"%s","consumed":%d,"stored":0,"reason":"all_items_failed_id_extraction"}`+"\n", resource, len(items))
			}
			anomalyEmitted = true
		} else if extractFailures > 0 && !anomalyEmitted {
			// Per-item primary-key resolution failure but at least one
			// item landed — emit one structured warning per resource per
			// sync run so users see the first occurrence of silent drops
			// instead of waiting for total failure.
			if humanFriendly {
				fmt.Fprintf(os.Stderr, "\nwarning: %s had %d item(s) on this page with no extractable primary key — those rows were dropped silently. Annotate the spec with x-resource-id to fix.\n", resource, extractFailures)
			} else {
				fmt.Fprintf(syncEvents, `{"event":"sync_anomaly","resource":"%s","consumed":%d,"stored":%d,"count":%d,"reason":"primary_key_unresolved"}`+"\n", resource, len(items), stored, extractFailures)
			}
			anomalyEmitted = true
		}

		totalCount += stored
		atomic.AddInt64(&progressCount, int64(stored))
		if resourceSupportsPagination(resource) && nextCursor == "" && pageSize.cursorParam != "offset" && len(items) >= pageSize.limit && pageMayHaveMore(data) {
			emitSyncMissingPaginationCursorWarning(syncEvents, humanFriendly, resource, "")
		}

		// Progress reporting (include rate limit info when active)
		currentRate := c.RateLimit()
		if humanFriendly {
			if currentRate > 0 {
				fmt.Fprintf(os.Stderr, "\r  %s: %d synced [%.1f req/s]", resource, atomic.LoadInt64(&progressCount), currentRate)
			} else {
				fmt.Fprintf(os.Stderr, "\r  %s: %d synced", resource, atomic.LoadInt64(&progressCount))
			}
		} else {
			if currentRate > 0 {
				fmt.Fprintf(syncEvents, `{"event":"sync_progress","resource":"%s","fetched":%d,"rate_rps":%.1f}`+"\n", resource, atomic.LoadInt64(&progressCount), currentRate)
			} else {
				fmt.Fprintf(syncEvents, `{"event":"sync_progress","resource":"%s","fetched":%d}`+"\n", resource, atomic.LoadInt64(&progressCount))
			}
		}

		pagesFetched++

		// Enforce page ceiling to prevent runaway syncs on large-catalog APIs.
		// Suppress the cap-hit warning when --latest-only is the cap source:
		// the template pinned maxPages=1 by user intent, and emitting one
		// warning per paginated resource would mask real sync_anomaly /
		// sync_error output in the same stream.
		if maxPages > 0 && pagesFetched >= maxPages {
			walkTruncated = true // PATCH(pagination-headers)
			truncatedByCap := resourceSupportsPagination(resource) && hasMore
			truncatedByCap = truncatedByCap && len(items) >= pageSize.limit
			if truncatedByCap {
				capExitCursor = nextCursor
			}
			if truncatedByCap && capExitCursor == "" {
				if pageSize.cursorType == "offset" {
					currentOffset, _ := strconv.Atoi(cursor)
					capExitCursor = strconv.Itoa(currentOffset + pageSize.limit)
				} else {
					truncatedByCap = false
				}
			}
			if truncatedByCap && capExitCursor != cursor {
				if !latestOnly {
					capExitHit = true
					if humanFriendly {
						fmt.Fprintf(os.Stderr, "\n  %s: reached --max-pages limit (%d pages, %d items)\n", resource, maxPages, totalCount)
					} else {
						fmt.Fprintf(syncEvents, `{"event":"sync_warning","resource":"%s","reason":"max_pages_cap_hit","message":"reached --max-pages cap of %d; data may be truncated. Re-run with --max-pages 0 (unlimited) or higher to verify."}`+"\n", resource, maxPages)
					}
				}
			}
			break
		}

		// Sticky-cursor detector: if the API echoes the same next cursor across
		// consecutive pages without advancing, abort to prevent burning the
		// --max-pages budget on a non-terminating loop. Checked AFTER the cap
		// guard so cap-hit takes precedence; checked BEFORE the natural-end
		// check below because the natural-end check would not catch a sticky
		// non-empty cursor on its own.
		if nextCursor != "" && nextCursor == lastNextCursor {
			if humanFriendly {
				fmt.Fprintf(os.Stderr, "\n  %s: API returned the same next cursor across two pages; aborting to prevent budget waste.\n", resource)
			} else {
				fmt.Fprintf(syncEvents, `{"event":"sync_warning","resource":"%s","reason":"stuck_pagination","message":"API returned the same next cursor across two pages for resource %s; aborting to prevent budget waste."}`+"\n", resource, resource)
			}
			walkTruncated = true // PATCH(pagination-headers)
			break
		}
		lastNextCursor = nextCursor

		// Determine if there are more pages.
		if !resourceSupportsPagination(resource) {
			break
		}
		if !hasMore || len(items) < pageSize.limit {
			break
		}
		if nextCursor == "" {
			if pageSize.cursorType == "offset" {
				// Cursor-based APIs return the next cursor in the envelope.
				// Offset-based APIs carry their pagination position client-side.
				currentOffset, _ := strconv.Atoi(cursor)
				nextCursor = strconv.Itoa(currentOffset + pageSize.limit)
			} else {
				// A cursor-based API reporting has_more without a next cursor
				// cannot advance safely; stop instead of looping silently.
				break
			}
		}

		// Save cursor after each page for resumability
		if err := db.SaveSyncState(resource, nextCursor, totalCount); err != nil {
			// Non-fatal: log and continue
			fmt.Fprintf(os.Stderr, "\nwarning: failed to save sync state for %s: %v\n", resource, err)
		}

		cursor = nextCursor
	}

	// Final sync state: clear cursor on natural completion, but preserve the
	// resume cursor when an operator intentionally capped the page budget.
	finalCursor := ""
	if capExitHit {
		finalCursor = capExitCursor
	}
	// PATCH(mirror-canonical-resource-name): persist the real row count, not this
	// run's running counter (issue #6 §3).
	_ = db.SaveSyncState(resource, finalCursor, syncStateTotalCount(db, resource, totalCount))

	// PATCH(pagination-headers): the completeness check issue #15 exists for.
	// Fiken-Api-Result-Count is what the API says the collection holds; a
	// complete walk that landed a different number of rows means the mirror is
	// short (issue #12 was exactly this, unseen). Recorded beside total_count so
	// doctor can show both.
	firstPageInfo := pageSink.PageInfo()
	landedRows := landed.Len()
	if firstPageInfo.HasResultCount && !walkTruncated && landedRows != firstPageInfo.ResultCount {
		emitResultCountMismatch(syncEvents, resource, "", firstPageInfo.ResultCount, landedRows)
	}
	recordSyncResultCount(db, resource, firstPageInfo.ResultCount, shouldRecordResultCount(firstPageInfo.HasResultCount, walkTruncated, windowedPull.Windowed))

	// F4b symptom probe: if items were consumed and successfully
	// extracted (extractFailures < consumed) but nothing landed in
	// the store, something downstream of extraction silently dropped
	// rows — FTS5 trigger error, transaction rollback, character
	// encoding. Emit a sync_anomaly so the symptom is visible the
	// next time it recurs; the underlying root cause is held out for
	// controlled repro.
	if consumedTotal > 0 && totalCount == 0 && extractFailureTotal < consumedTotal {
		if humanFriendly {
			fmt.Fprintf(os.Stderr, "\nwarning: %s consumed %d items, extracted %d primary keys, but stored 0 rows — extraction succeeded yet nothing landed. Investigate FTS triggers / transaction rollback / encoding.\n", resource, consumedTotal, consumedTotal-extractFailureTotal)
		} else {
			fmt.Fprintf(syncEvents, `{"event":"sync_anomaly","resource":"%s","consumed":%d,"stored":0,"extract_failures":%d,"reason":"stored_count_zero_after_extraction"}`+"\n", resource, consumedTotal, extractFailureTotal)
		}
	}

	if !humanFriendly {
		fmt.Fprintf(syncEvents, `{"event":"sync_complete","resource":"%s","total":%d,"duration_ms":%d}`+"\n", resource, totalCount, time.Since(started).Milliseconds())
	}

	return syncResult{Resource: resource, Count: totalCount, Duration: time.Since(started)}
}

// paginationDefaults holds the resolved pagination parameter names and page size.
type paginationDefaults struct {
	cursorParam string
	cursorType  string // paginator class: "", "cursor", "page_token", "offset", "page"
	limitParam  string
	limit       int
	// PATCH(pagination-zero-based): the spec default for the cursor parameter,
	// i.e. the page the server serves when the request carries no cursor. This
	// API declares `page` with default 0, so page numbering is 0-based and the
	// page after the first is 1, not 2 (issue #12).
	firstPage int
}

// determinePaginationDefaults returns the pagination parameter names to use.
// Values are detected from the API spec by the profiler at generation time.
func determinePaginationDefaults() paginationDefaults {
	return paginationDefaults{
		cursorParam: "page",
		cursorType:  "page",
		limitParam:  "pageSize",
		limit:       100,
		// PATCH(pagination-zero-based): spec default of the `page` parameter.
		firstPage: 0,
	}
}

func resourceSupportsPagination(resource string) bool {
	switch resource {
	case "accounts":
		return true
	case "bank_accounts":
		return true
	case "companies":
		return true
	case "contacts":
		return true
	// PATCH(sync-invoices-creditnotes): both list operations declare the shared
	// page/pageSize parameters and return the Fiken-Api-Page-Count and
	// Fiken-Api-Result-Count headers (spec.yaml:1362, :1795) — issue #18.
	case "credit_notes":
		return true
	case "inbox":
		return true
	case "invoices":
		return true
	case "journal_entries":
		return true
	case "products":
		return true
	case "projects":
		return true
	case "purchases":
		return true
	case "sales":
		return true
	case "transactions":
		return true
	}
	return false
}

// syncResourceSinceParam returns the query parameter name this resource's
// list endpoint declares for incremental temporal filtering, or "" when the
// endpoint declares none. Skipping the param for "" resources avoids
// validation-error 400s on APIs that reject unknown query keys.
func syncResourceSinceParam(resource string) string {
	switch resource {
	// PATCH(sync-since-last-modified): the printed switch was empty, so every
	// --since was discarded and every sync was a full re-pull of every page of
	// every resource (issue #13). Only an explicit --since reaches here: the
	// stored watermark is never applied to a resource in this list, because the
	// dependent walker that owns all five does not read it. spec.yaml
	// declares the lastModifiedGe parameter on these five synced list
	// operations: getContacts (:718), getJournalEntries (:1131),
	// getTransactions (:1274), getProducts (:2770) and getSales (:2914).
	// purchases declares no filter and carries no lastModifiedDate; accounts,
	// bank_accounts, companies, inbox and projects declare no date filter at
	// all, so they keep the resource_not_incremental warning and a full pull.
	case "contacts", "journal_entries", "transactions", "products", "sales":
		return "lastModifiedGe"
	// PATCH(sync-invoices-creditnotes): getInvoices (spec.yaml:1381) and
	// getCreditNotes (spec.yaml:1815) declare the same shared lastModifiedGe
	// parameter; they were outside the list above only because neither was a
	// sync resource before issue #18. Kept as its own arm so the five-name
	// needle the sync-since-last-modified record greps for still resolves.
	case "invoices", "credit_notes":
		return "lastModifiedGe"
	}
	return ""
}

func syncResourceSinceParamFormat(resource string) string {
	switch resource {
	// PATCH(sync-since-last-modified): components.parameters.lastModifiedGe is
	// `type: string, format: date` — YYYY-MM-DD — which is the spelling
	// formatSyncSinceValue's day arm matches on.
	case "contacts", "journal_entries", "transactions", "products", "sales":
		return "date"
	// PATCH(sync-invoices-creditnotes): same shared components.parameters
	// .lastModifiedGe, so the same `type: string, format: date` (issue #18).
	case "invoices", "credit_notes":
		return "date"
	}
	return ""
}

func formatSyncSinceValue(value string, paramFormat string) string {
	if strings.EqualFold(paramFormat, "date") {
		if ts, err := time.Parse(time.RFC3339, value); err == nil {
			return ts.Format("2006-01-02")
		}
		if ts, err := time.Parse(time.RFC3339Nano, value); err == nil {
			return ts.Format("2006-01-02")
		}
		if _, err := time.Parse("2006-01-02", value); err == nil {
			return value
		}
	}
	return value
}

// extractPageItems attempts to extract an array of items and pagination cursor from a response.
// It tries multiple strategies:
// 1. Direct JSON array
// 2. Common wrapper keys: "data", "results", "items", "records", "nodes", "entries"
// 3. JSend-style nested data envelopes: {"data":{"<resource>":[...]}}
// It also extracts the next cursor from common response fields.
func extractPageItems(data json.RawMessage, cursorParam string) ([]json.RawMessage, string, bool) {
	// Strategy 1: direct array
	var items []json.RawMessage
	if err := json.Unmarshal(data, &items); err == nil {
		return items, "", false
	}

	// Strategy 2: object with known wrapper keys
	var envelope map[string]json.RawMessage
	if err := json.Unmarshal(data, &envelope); err != nil {
		return nil, "", false
	}

	if items, ok := extractItemsByKnownKeys(envelope); ok {
		nextCursor, hasMore := extractPaginationFromEnvelope(envelope, cursorParam)
		return items, nextCursor, hasMore
	}

	for _, key := range dataEnvelopeKeys {
		raw, ok := envelope[key]
		if !ok {
			continue
		}
		var inner map[string]json.RawMessage
		if json.Unmarshal(raw, &inner) != nil {
			continue
		}
		if items, ok := extractItemsFromEnvelope(inner); ok {
			nextCursor, hasMore := extractPaginationFromEnvelope(inner, cursorParam)
			outerCursor, outerHasMore := extractPaginationFromEnvelope(envelope, cursorParam)
			if nextCursor == "" {
				nextCursor = outerCursor
			}
			hasMore = hasMore || outerHasMore
			return items, nextCursor, hasMore
		}
	}

	if items, ok := extractSingleObjectArraySibling(envelope); ok {
		nextCursor, hasMore := extractPaginationFromEnvelope(envelope, cursorParam)
		return items, nextCursor, hasMore
	}

	return nil, "", false
}

func extractItemsFromEnvelope(envelope map[string]json.RawMessage) ([]json.RawMessage, bool) {
	if items, ok := extractItemsByKnownKeys(envelope); ok {
		return items, true
	}
	return extractSingleObjectArraySibling(envelope)
}

func extractItemsByKnownKeys(envelope map[string]json.RawMessage) ([]json.RawMessage, bool) {
	for _, key := range pageItemKeys {
		if raw, ok := envelope[key]; ok {
			if items, ok := extractObjectArray(raw); ok {
				return items, true
			}
		}
	}
	return nil, false
}

func extractSingleObjectArraySibling(envelope map[string]json.RawMessage) ([]json.RawMessage, bool) {
	// Fallback: try every key in the envelope. If exactly one maps to a JSON
	// array with items, use it. This handles APIs that wrap responses with the
	// resource name alongside arbitrary scalar metadata
	// (e.g., {"markets": [...], "request_id": "..."}).
	var arrayItems []json.RawMessage
	arrayCount := 0
	for key, raw := range envelope {
		if pageMetadataArrayKeys[key] {
			continue
		}
		if candidate, ok := extractObjectArray(raw); ok {
			arrayItems = candidate
			arrayCount++
			continue
		}
		var rawArray []json.RawMessage
		if json.Unmarshal(raw, &rawArray) == nil && !isJSONNull(raw) {
			continue
		}
	}
	if arrayCount == 1 {
		return arrayItems, true
	}
	return nil, false
}

func extractObjectArray(raw json.RawMessage) ([]json.RawMessage, bool) {
	var items []json.RawMessage
	if err := json.Unmarshal(raw, &items); err != nil || len(items) == 0 {
		return nil, false
	}
	var obj map[string]json.RawMessage
	if err := json.Unmarshal(items[0], &obj); err != nil {
		return nil, false
	}
	return items, true
}

// isDryRunResponse detects the `{"dry_run": true}` sentinel that
// client.dryRun returns instead of a real API response. The sync loop
// uses this to short-circuit before the upsert path, which would
// otherwise fail with "missing id for <resource>" against a sentinel
// that has no items and no id. The check requires exactly one key
// (dry_run) so a live API response that happens to include a top-level
// dry_run field alongside real data isn't misclassified as the
// sentinel and silently zero out the sync count.
func isDryRunResponse(data json.RawMessage) bool {
	var envelope map[string]json.RawMessage
	if err := json.Unmarshal(data, &envelope); err != nil {
		return false
	}
	if len(envelope) != 1 {
		return false
	}
	raw, ok := envelope["dry_run"]
	if !ok {
		return false
	}
	var v bool
	return json.Unmarshal(raw, &v) == nil && v
}

func isEmptyPageResponse(data json.RawMessage) bool {
	var direct []json.RawMessage
	if err := json.Unmarshal(data, &direct); err == nil && !isJSONNull(data) {
		return len(direct) == 0
	}

	var envelope map[string]json.RawMessage
	if err := json.Unmarshal(data, &envelope); err != nil {
		return false
	}

	if isEmptyPageEnvelope(envelope) {
		return true
	}

	for _, key := range dataEnvelopeKeys {
		raw, ok := envelope[key]
		if !ok {
			continue
		}
		if isJSONNull(raw) {
			if envelopeReportsFailure(envelope) {
				return true
			}
			continue
		}
		var inner map[string]json.RawMessage
		if json.Unmarshal(raw, &inner) == nil && isEmptyPageEnvelope(inner) {
			return true
		}
	}

	return false
}

func envelopeReportsFailure(envelope map[string]json.RawMessage) bool {
	for _, key := range []string{"success", "Success"} {
		if raw, ok := envelope[key]; ok {
			var success bool
			if json.Unmarshal(raw, &success) == nil {
				return !success
			}
		}
	}
	for _, key := range []string{"status", "Status"} {
		if raw, ok := envelope[key]; ok {
			var status string
			if json.Unmarshal(raw, &status) == nil {
				switch strings.ToLower(status) {
				case "error", "fail", "failed":
					return true
				}
				return false
			}
		}
	}
	return false
}

func isEmptyPageEnvelope(envelope map[string]json.RawMessage) bool {
	for _, key := range pageItemKeys {
		if raw, ok := envelope[key]; ok {
			var items []json.RawMessage
			if err := json.Unmarshal(raw, &items); err == nil && !isJSONNull(raw) {
				if len(items) > 0 {
					var obj map[string]json.RawMessage
					if err := json.Unmarshal(items[0], &obj); err != nil {
						continue
					}
				}
				return len(items) == 0
			}
		}
	}
	if hasExactlyOneNullArrayWithZeroCount(envelope) {
		return true
	}
	return hasExactlyOneEmptyArray(envelope)
}

func hasExactlyOneNullArrayWithZeroCount(envelope map[string]json.RawMessage) bool {
	nullArrayCount := 0
	hasZeroCount := false
	for key, raw := range envelope {
		if isZeroCountField(key, raw) {
			hasZeroCount = true
			continue
		}
		if isJSONNull(raw) && isNullPageItemCandidateKey(key) {
			nullArrayCount++
			continue
		}
		if pageEnvelopeMetadataKeys[key] {
			continue
		}
		return false
	}
	return nullArrayCount == 1 && hasZeroCount
}

func isZeroCountField(key string, raw json.RawMessage) bool {
	switch key {
	case "total", "Total", "count", "Count", "total_count", "totalCount", "TotalCount":
	default:
		return false
	}
	// A JSON null count is not a numeric zero-count signal: json.Unmarshal of
	// "null" into a float64 is a no-op (leaves n at 0, returns nil), so without
	// this guard a null count would falsely qualify as zero — masking a
	// possibly-malformed {"items":null,"total":null} as an empty page.
	if isJSONNull(raw) {
		return false
	}
	var n float64
	return json.Unmarshal(raw, &n) == nil && n == 0
}

func isNullPageItemCandidateKey(key string) bool {
	for _, itemKey := range pageItemKeys {
		if key == itemKey {
			return true
		}
	}
	return !pageEnvelopeMetadataKeys[key]
}

func hasExactlyOneEmptyArray(envelope map[string]json.RawMessage) bool {
	arrayCount := 0
	for _, raw := range envelope {
		var candidate []json.RawMessage
		if err := json.Unmarshal(raw, &candidate); err == nil && !isJSONNull(raw) {
			// Skip candidate arrays that contain primitives (not objects).
			if len(candidate) > 0 {
				var obj map[string]json.RawMessage
				if err := json.Unmarshal(candidate[0], &obj); err != nil {
					continue
				}
			}
			if len(candidate) == 0 {
				arrayCount++
			}
		}
	}
	return arrayCount == 1
}

func isJSONNull(raw json.RawMessage) bool {
	return strings.TrimSpace(string(raw)) == "null"
}

func isJSONResponse(data json.RawMessage) bool {
	var probe any
	return json.Unmarshal(data, &probe) == nil
}

// extractPaginationFromEnvelope extracts cursor and has_more from a response envelope.
func extractPaginationFromEnvelope(envelope map[string]json.RawMessage, cursorParam string) (string, bool) {
	var hasMore bool

	nextCursor := nextCursorFromLinks(envelope, cursorParam)

	// Try common cursor field names
	cursorKeys := []string{
		"next_cursor", "nextCursor", "next_token", "nextToken", "cursor",
		"next_page_token", "nextPageToken", "page_token", "after", "end_cursor", "endCursor",
	}
	if nextCursor == "" {
		nextCursor = findCursorInMap(envelope, cursorKeys)
	}

	// If no top-level cursor was found, look one level deeper into well-known
	// pagination wrapper objects. Slack returns {"messages":[...],
	// "response_metadata":{"next_cursor":"..."}}; Pipedrive uses
	// "additional_data"; MongoDB Atlas uses "pagination"; many APIs use
	// "meta" or "paging". Purely additive — only
	// runs when the top-level scan returned empty — and uses the same
	// cursorKeys set so wrapper contents go through the same name match.
	if nextCursor == "" {
		paginationWrapperKeys := []string{"response_metadata", "additional_data", "pagination", "meta", "paging"}
		for _, wrapperKey := range paginationWrapperKeys {
			rawWrapper, ok := envelope[wrapperKey]
			if !ok {
				continue
			}
			var inner map[string]json.RawMessage
			if json.Unmarshal(rawWrapper, &inner) != nil {
				continue
			}
			if c := findCursorInMap(inner, cursorKeys); c != "" {
				nextCursor = c
				break
			}
		}
	}

	if nextCursor == "" {
		nextCursor = nextCursorFromTopLevelURL(envelope, cursorParam)
	}

	// Try common has_more field names
	hasMoreKeys := []string{"has_more", "hasMore", "has_next", "hasNext", "next_page"}
	for _, key := range hasMoreKeys {
		if raw, ok := envelope[key]; ok {
			if err := json.Unmarshal(raw, &hasMore); err == nil {
				break
			}
		}
	}

	// If we found a cursor, assume there are more pages even without explicit has_more
	if nextCursor != "" && !hasMore {
		hasMore = true
	}

	return nextCursor, hasMore
}

func pageAllowsPageIntFallback(data json.RawMessage) bool {
	return pageMayHaveMore(data)
}

func pageMayHaveMore(data json.RawMessage) bool {
	hasMore, parsed := pageExplicitHasMore(data)
	return !parsed || hasMore
}

func pageExplicitHasMore(data json.RawMessage) (bool, bool) {
	var envelope map[string]json.RawMessage
	if err := json.Unmarshal(data, &envelope); err != nil {
		return false, false
	}
	if hasMore, parsed := envelopeExplicitHasMore(envelope); parsed {
		return hasMore, true
	}
	for _, key := range dataEnvelopeKeys {
		raw, ok := envelope[key]
		if !ok {
			continue
		}
		var inner map[string]json.RawMessage
		if json.Unmarshal(raw, &inner) == nil {
			if hasMore, parsed := envelopeExplicitHasMore(inner); parsed {
				return hasMore, true
			}
		}
	}
	return false, false
}

func envelopeExplicitHasMore(envelope map[string]json.RawMessage) (bool, bool) {
	for _, key := range []string{"has_more", "hasMore", "has_next", "hasNext", "next_page"} {
		raw, ok := envelope[key]
		if !ok {
			continue
		}
		var hasMore bool
		if json.Unmarshal(raw, &hasMore) == nil {
			return hasMore, true
		}
	}
	return false, false
}

// nextCursorFromLinks extracts JSON:API-style pagination cursors from
// {"links":{"next":"https://example.com/items?page[cursor]=..."}}.
func nextCursorFromLinks(envelope map[string]json.RawMessage, cursorParam string) string {
	rawLinks, ok := envelope["links"]
	if !ok {
		return ""
	}
	var links map[string]json.RawMessage
	if json.Unmarshal(rawLinks, &links) != nil {
		return ""
	}
	rawNext, ok := links["next"]
	if !ok {
		return ""
	}
	var nextURL string
	if json.Unmarshal(rawNext, &nextURL) != nil || nextURL == "" {
		return ""
	}

	return cursorFromNextURL(nextURL, cursorParam)
}

// nextCursorFromTopLevelURL extracts a cursor from top-level absolute or relative next URLs.
func nextCursorFromTopLevelURL(envelope map[string]json.RawMessage, cursorParam string) string {
	for _, key := range []string{"next", "next_url"} {
		rawNext, ok := envelope[key]
		if !ok {
			continue
		}
		var nextURL string
		if json.Unmarshal(rawNext, &nextURL) != nil || nextURL == "" {
			continue
		}
		if isFollowableNextURL(nextURL) {
			return cursorFromNextURL(nextURL, cursorParam)
		}
	}
	return ""
}

// isFollowableNextURL reports whether a top-level "next" string is a URL we can
// pull a cursor query param from: an absolute http(s) URL, a root-relative path,
// or any value carrying a query string. Bare opaque cursor tokens (no query)
// are rejected so they aren't mis-parsed.
func isFollowableNextURL(nextURL string) bool {
	lower := strings.ToLower(nextURL)
	return strings.HasPrefix(lower, "http") ||
		strings.HasPrefix(nextURL, "/") ||
		strings.Contains(nextURL, "?")
}

func cursorFromNextURL(nextURL string, cursorParam string) string {
	cursorKeys := []string{cursorParam}
	if cursorParam != "page[cursor]" {
		cursorKeys = append(cursorKeys, "page[cursor]")
	}
	if cursorParam != "cursor" {
		cursorKeys = append(cursorKeys, "cursor")
	}
	if cursorParam != "after" {
		cursorKeys = append(cursorKeys, "after")
	}

	parsed, err := url.Parse(nextURL)
	if err != nil {
		return ""
	}
	values := parsed.Query()
	for _, key := range cursorKeys {
		if key == "" {
			continue
		}
		if cursor := values.Get(key); cursor != "" {
			return cursor
		}
	}
	return ""
}

// findCursorInMap returns the first non-empty string-typed value in m
// whose key matches one of cursorKeys. Used by extractPaginationFromEnvelope
// to scan both the top-level envelope and well-known wrapper objects with
// the same name-match rules — extracted so the two scans can't drift.
func findCursorInMap(m map[string]json.RawMessage, cursorKeys []string) string {
	for _, key := range cursorKeys {
		raw, ok := m[key]
		if !ok {
			continue
		}
		var s string
		if err := json.Unmarshal(raw, &s); err == nil && s != "" {
			return s
		}
	}
	return ""
}

func emitSyncMissingPaginationCursorWarning(syncEvents io.Writer, humanFriendly bool, resource, parent string) {
	if humanFriendly {
		if parent != "" {
			fmt.Fprintf(os.Stderr, "\nwarning: %s returned a full page for parent %s without a next cursor; data may be truncated.\n", resource, parent)
			return
		}
		fmt.Fprintf(os.Stderr, "\nwarning: %s returned a full page without a next cursor; data may be truncated.\n", resource)
		return
	}
	if parent != "" {
		fmt.Fprintf(syncEvents, `{"event":"sync_warning","resource":"%s","parent":"%s","reason":"pagination_cursor_missing","message":"API returned a full page without a usable next cursor; data may be truncated."}`+"\n", resource, parent)
		return
	}
	fmt.Fprintf(syncEvents, `{"event":"sync_warning","resource":"%s","reason":"pagination_cursor_missing","message":"API returned a full page without a usable next cursor; data may be truncated."}`+"\n", resource)
}

type discriminatorDispatch struct {
	Field  string
	Values map[string]string
}

var discriminatorDispatchers = map[string]discriminatorDispatch{}

func upsertResourceBatch(db *store.Store, resource string, items []json.RawMessage) (int, int, error) {
	// PATCH(attachment-dedupe): the API serves the same attachment twice inside
	// the parent blob (78 of 85 sales on the test company), so every report that
	// counts or lists attachments double-counts. Cleaned here, before the upsert,
	// because the detectors and the MCP sql tool read the STORED blob, not the
	// response (issue #10).
	items = dedupeAttachmentArrays(resource, items)
	if _, ok := discriminatorDispatchers[resource]; !ok {
		return db.UpsertBatch(resource, items)
	}

	grouped := map[string][]json.RawMessage{}
	order := []string{}
	for _, item := range items {
		target := resource
		if obj, err := store.DecodeJSONObject(item); err == nil {
			target = resolveDiscriminatedResource(resource, obj)
		}
		if _, ok := grouped[target]; !ok {
			order = append(order, target)
		}
		grouped[target] = append(grouped[target], item)
	}

	var stored, extractFailures int
	for _, target := range order {
		targetStored, targetExtractFailures, err := db.UpsertBatch(target, grouped[target])
		if err != nil {
			return stored, extractFailures + targetExtractFailures, err
		}
		stored += targetStored
		extractFailures += targetExtractFailures
	}
	return stored, extractFailures, nil
}

func resolveDiscriminatedResource(resource string, obj map[string]any) string {
	dispatcher, ok := discriminatorDispatchers[resource]
	if !ok || dispatcher.Field == "" {
		return resource
	}
	value := store.LookupFieldValue(obj, dispatcher.Field)
	if value == nil {
		return resource
	}
	if target, ok := dispatcher.Values[fmt.Sprintf("%v", value)]; ok && target != "" {
		return target
	}
	return resource
}

// upsertSingleObject stores a non-array API response as a single record.
func upsertSingleObject(db *store.Store, resource string, data json.RawMessage) error {
	obj, err := store.DecodeJSONObject(data)
	if err != nil {
		// Not a JSON object either - store raw under resource name
		return db.Upsert(resource, resource, data)
	}

	resource = resolveDiscriminatedResource(resource, obj)

	// PATCH(mirror-canonical-resource-name): one spelling before anything keys on
	// the name — the dispatch below, extractID's override map and the resource_type
	// column. The printed switch spelled bank-accounts/journal-entries with a
	// hyphen while the sync registry spells them with an underscore, so those two
	// resources never reached their typed table (issue #6 §1).
	canonicalResource, cerr := store.CanonicalResource(resource)
	if cerr != nil {
		return cerr
	}
	resource = canonicalResource

	id := extractID(resource, obj)
	if id == "" {
		id = resource
	}

	switch resource {
	case "accounts":
		return db.UpsertAccounts(data)
	case "bank_accounts":
		return db.UpsertBankAccounts(data)
	case "contacts":
		return db.UpsertContacts(data)
	case "contacts_attachments":
		return db.UpsertContactsAttachments(data)
	case "contact_person":
		return db.UpsertContactPerson(data)
	case "inbox":
		return db.UpsertInbox(data)
	case "invoices_attachments":
		return db.UpsertInvoicesAttachments(data)
	case "journal_entries":
		return db.UpsertJournalEntries(data)
	case "journal_entries_attachments":
		return db.UpsertJournalEntriesAttachments(data)
	case "create_invoice_draft":
		return db.UpsertCreateInvoiceDraft(data)
	case "products":
		return db.UpsertProducts(data)
	case "projects":
		return db.UpsertProjects(data)
	case "purchases":
		return db.UpsertPurchases(data)
	case "purchases_attachments":
		return db.UpsertPurchasesAttachments(data)
	case "purchases_delete":
		return db.UpsertPurchasesDelete(data)
	case "purchases_payments":
		return db.UpsertPurchasesPayments(data)
	case "sales":
		return db.UpsertSales(data)
	case "sales_attachments":
		return db.UpsertSalesAttachments(data)
	case "sales_delete":
		return db.UpsertSalesDelete(data)
	case "sales_payments":
		return db.UpsertSalesPayments(data)
	case "settled":
		return db.UpsertSettled(data)
	case "write_off":
		return db.UpsertWriteOff(data)
	case "transactions":
		return db.UpsertTransactions(data)
	case "transactions_delete":
		return db.UpsertTransactionsDelete(data)
	default:
		// PATCH(mirror-canonical-resource-name): a canonical name that owns a typed
		// table must have matched an arm above; reaching the generic write means the
		// switch is out of step with internal/store/resource_name.go (issue #6).
		if store.HasTypedTable(resource) {
			return fmt.Errorf("upsertSingleObject: %q has a typed table but reached the generic default arm", resource)
		}
		return db.Upsert(resource, id, data)
	}
}

// parseSinceDuration converts human-friendly duration strings into a time.Time.
// Supported formats: "7d" (days), "24h" (hours), "30m" (minutes), "1w" (weeks).
func parseSinceDuration(s string) (time.Time, error) {
	re := regexp.MustCompile(`^(\d+)([dhwm])$`)
	matches := re.FindStringSubmatch(strings.TrimSpace(s))
	if matches == nil {
		return time.Time{}, fmt.Errorf("expected format like 7d, 24h, 1w, or 30m")
	}

	n, err := strconv.Atoi(matches[1])
	if err != nil {
		return time.Time{}, err
	}

	now := time.Now()
	switch matches[2] {
	case "d":
		return now.Add(-time.Duration(n) * 24 * time.Hour), nil
	case "h":
		return now.Add(-time.Duration(n) * time.Hour), nil
	case "w":
		return now.Add(-time.Duration(n) * 7 * 24 * time.Hour), nil
	case "m":
		return now.Add(-time.Duration(n) * time.Minute), nil
	default:
		return time.Time{}, fmt.Errorf("unknown unit %q", matches[2])
	}
}

func defaultSyncResources() []string {
	return []string{
		"companies",
	}
}

// knownSyncResourceNames returns every resource name sync will accept —
// flat resources plus any parent-child dependents. Used by --resource-param
// validation to reject misspellings before they become silent no-ops.
func knownSyncResourceNames() []string {
	names := []string{
		"companies",
	}
	for _, dep := range dependentResourceDefs() {
		names = append(names, dep.Name)
	}
	return names
}

// syncResourcePath maps resource names to their actual API endpoint paths.
// For REST APIs this is typically "/<resource>". For non-REST APIs (e.g., Steam)
// this preserves the actual endpoint path like "/ISteamApps/GetAppList/v2".
func syncResourcePath(resource string) (string, error) {
	paths := map[string]string{
		"companies": "/companies",
	}
	if p, ok := paths[resource]; ok {
		return p, nil
	}
	return "", fmt.Errorf("unknown sync resource %q", resource)
}

// dependentResourceDef describes a child resource that requires iterating parent IDs to sync.
// When KeyField is non-empty, the dependent's parent IDs are extracted from the parent
// records' KeyField via json_extract rather than from the parent table's primary key.
// Populated from a spec-declared walker (Endpoint.Walker.KeyField in internal YAML,
// or `key_field` under `x-pp-sync-walker` in OpenAPI). Empty KeyField preserves the
// parent-primary-key flow.
type dependentResourceDef struct {
	Name          string
	ParentTable   string
	ParentIDParam string
	PathTemplate  string
	KeyField      string
	PathParams    []dependentPathParamDef
}

type dependentPathParamDef struct {
	Param string
	Field string
}

func dependentResourceDefs() []dependentResourceDef {
	return []dependentResourceDef{
		{Name: "accounts", ParentTable: "companies", ParentIDParam: "companySlug", PathTemplate: "/companies/{companySlug}/accounts", KeyField: "slug", PathParams: []dependentPathParamDef{
			{Param: "companySlug", Field: "slug"},
		}},
		{Name: "bank_accounts", ParentTable: "companies", ParentIDParam: "companySlug", PathTemplate: "/companies/{companySlug}/bankAccounts", KeyField: "slug", PathParams: []dependentPathParamDef{
			{Param: "companySlug", Field: "slug"},
		}},
		{Name: "contacts", ParentTable: "companies", ParentIDParam: "companySlug", PathTemplate: "/companies/{companySlug}/contacts", KeyField: "slug", PathParams: []dependentPathParamDef{
			{Param: "companySlug", Field: "slug"},
		}},
		// PATCH(sync-invoices-creditnotes): getCreditNotes (spec.yaml:1795) is a
		// paged bare array with the Fiken-Api-* headers, exactly like the ten
		// dependents the printer emitted; it was left out only because the
		// profiler picked one list operation per tag (issue #18).
		{Name: "credit_notes", ParentTable: "companies", ParentIDParam: "companySlug", PathTemplate: "/companies/{companySlug}/creditNotes", KeyField: "slug", PathParams: []dependentPathParamDef{
			{Param: "companySlug", Field: "slug"},
		}},
		{Name: "inbox", ParentTable: "companies", ParentIDParam: "companySlug", PathTemplate: "/companies/{companySlug}/inbox", KeyField: "slug", PathParams: []dependentPathParamDef{
			{Param: "companySlug", Field: "slug"},
		}},
		// PATCH(sync-invoices-creditnotes): getInvoices (spec.yaml:1362) carries
		// issueDate, dueDate, invoiceNumber and dispatches[], none of which the
		// sale blob holds, so a bookkeeping mirror without it cannot answer a
		// settlement or dispatch question at all (issue #18).
		{Name: "invoices", ParentTable: "companies", ParentIDParam: "companySlug", PathTemplate: "/companies/{companySlug}/invoices", KeyField: "slug", PathParams: []dependentPathParamDef{
			{Param: "companySlug", Field: "slug"},
		}},
		{Name: "journal_entries", ParentTable: "companies", ParentIDParam: "companySlug", PathTemplate: "/companies/{companySlug}/journalEntries", KeyField: "slug", PathParams: []dependentPathParamDef{
			{Param: "companySlug", Field: "slug"},
		}},
		{Name: "products", ParentTable: "companies", ParentIDParam: "companySlug", PathTemplate: "/companies/{companySlug}/products", KeyField: "slug", PathParams: []dependentPathParamDef{
			{Param: "companySlug", Field: "slug"},
		}},
		{Name: "projects", ParentTable: "companies", ParentIDParam: "companySlug", PathTemplate: "/companies/{companySlug}/projects", KeyField: "slug", PathParams: []dependentPathParamDef{
			{Param: "companySlug", Field: "slug"},
		}},
		{Name: "purchases", ParentTable: "companies", ParentIDParam: "companySlug", PathTemplate: "/companies/{companySlug}/purchases", KeyField: "slug", PathParams: []dependentPathParamDef{
			{Param: "companySlug", Field: "slug"},
		}},
		{Name: "sales", ParentTable: "companies", ParentIDParam: "companySlug", PathTemplate: "/companies/{companySlug}/sales", KeyField: "slug", PathParams: []dependentPathParamDef{
			{Param: "companySlug", Field: "slug"},
		}},
		{Name: "transactions", ParentTable: "companies", ParentIDParam: "companySlug", PathTemplate: "/companies/{companySlug}/transactions", KeyField: "slug", PathParams: []dependentPathParamDef{
			{Param: "companySlug", Field: "slug"},
		}},
	}
}

// syncDependentResources iterates parent tables and syncs child resources per parent ID.
// parentFilter mirrors the user's --resources flag (empty = sync everything). A dependent
// runs when its parent table or its own name appears in the filter.
func syncDependentResources(ctx context.Context, c interface {
	Get(context.Context, string, map[string]string) (json.RawMessage, error)
	RateLimit() float64
}, db *store.Store, sinceTS string, full bool, maxPages int, latestOnly bool, parentFilter []string, userParams *syncUserParams, syncEvents io.Writer) []syncResult {
	allow := make(map[string]bool, len(parentFilter))
	for _, r := range parentFilter {
		allow[r] = true
	}
	var results []syncResult
	for _, dep := range dependentResourceDefs() {
		if len(allow) > 0 && !allow[dep.ParentTable] && !allow[dep.Name] {
			continue
		}
		res := syncDependentResource(ctx, c, db, dep, sinceTS, full, maxPages, latestOnly, userParams, syncEvents)
		results = append(results, res)
	}
	return results
}

// syncDependentResource syncs a single child resource by iterating all parent IDs.
func syncDependentResource(ctx context.Context, c interface {
	Get(context.Context, string, map[string]string) (json.RawMessage, error)
	RateLimit() float64
}, db *store.Store, dep dependentResourceDef, sinceTS string, full bool, maxPages int, latestOnly bool, userParams *syncUserParams, syncEvents io.Writer) syncResult {
	started := time.Now()
	if syncEvents == nil {
		syncEvents = io.Discard
	}
	// PATCH(pagination-headers): one sink for the whole dependent walk, reset
	// per parent — Fiken-Api-Result-Count describes one company's collection,
	// so the comparison is per (company, resource) (issue #15).
	ctx, pageSink := client.NewPageInfoContext(ctx)

	pathParams := dep.PathParams
	if len(pathParams) == 0 {
		field := "id"
		if dep.KeyField != "" {
			field = dep.KeyField
		}
		pathParams = []dependentPathParamDef{{Param: dep.ParentIDParam, Field: field}}
	}
	parentRows, err := dependentParentRows(db, dep.ParentTable, pathParams)
	// PATCH(sync-named-dependents): the error is tested FIRST. Every error path
	// of dependentParentRows returns nil rows, so an err-or-empty branch that
	// looked at the rows first reported a locked or corrupt mirror as
	// parent_table_empty, with a hint to sync a parent table that may be full
	// (issue #14 follow-up).
	if err != nil {
		return syncResult{Resource: dep.Name, Err: fmt.Errorf("querying parent table %s: %w", dep.ParentTable, err), Duration: time.Since(started)}
	}
	unscopedParents := len(parentRows)
	// PATCH(mirror-canonical-resource-name): honour --company.
	parentRows = scopeParentRowsToCompany(dep.ParentTable, parentRows)
	if len(parentRows) == 0 {
		// PATCH(sync-named-dependents): a machine-mode run used to read this as a
		// plain success (issue #14 follow-up). An empty parent TABLE and a
		// --company slug that matches no parent row are different repairs, so
		// they are different reasons.
		if unscopedParents > 0 {
			return dependentCompanyNotInParentResult(syncEvents, dep.Name, dep.ParentTable, syncCompanyScope, started)
		}
		return dependentParentEmptyResult(syncEvents, dep.Name, dep.ParentTable, started)
	}

	if humanFriendly {
		fmt.Fprintf(os.Stderr, "  %s: syncing for %d %s parents\n", dep.Name, len(parentRows), dep.ParentTable)
	}

	var totalCount int
	var deniedParents int
	var firstDenial *accessWarning
	pageSize := determinePaginationDefaults()
	depSinceParam := syncSinceParamFor(dep.Name) // PATCH(pagination-headers)
	// PATCH(sync-since-last-modified): sinceTS is the EXPLICIT --since and
	// nothing else; it is a caller window, applied to every parent alike.
	// PATCH(sync-watermark): the DEFAULT path (no --since, no --full) is
	// windowed too, but per parent rather than per resource — the watermark is
	// keyed by (company, resource), so it is read inside the parent loop below
	// and not here (issue #22). `full` is consulted there as well: it clears
	// the pair's watermark before refetching it. --full with --since stays
	// refused at flag validation, because that combination clears rows it would
	// then not refetch.
	depSinceTS := sinceTS
	if depSinceTS != "" && depSinceParam == "" {
		if humanFriendly {
			fmt.Fprintf(os.Stderr, "  %s: incremental sync ignored (endpoint declares no temporal filter; falling back to full pagination)\n", dep.Name)
		} else {
			fmt.Fprintf(syncEvents, `{"event":"sync_warning","resource":"%s","reason":"resource_not_incremental","message":"endpoint does not declare a temporal filter parameter; incremental sync has no effect for this resource"}`+"\n", dep.Name)
		}
		depSinceTS = ""
	}
	if depSinceTS != "" {
		// PATCH(sync-since-last-modified): same day-floor-minus-one window as
		// the flat walker (issue #13).
		depSinceTS = syncSinceWindowValue(depSinceTS, syncSinceParamFormatFor(dep.Name))
	}
	// Per-resource extract-failure tracking for the F4b symptom probe and
	// per-item primary_key_unresolved warning. See syncResource for the
	// concurrency rationale (one goroutine per resource → no race).
	var depExtractFailureTotal int
	var depConsumedTotal int
	depAnomalyEmitted := false
	// PATCH(pagination-headers): the API's own row count, summed over the
	// parents this run walked, and whether every one of them reported it.
	depResultCountTotal := 0
	depParentsWithResultCount := 0
	depParentsDeniedAndEmpty := 0
	depWalkTruncated := false
	// PATCH(pagination-headers): distinct storage keys landed for the parent
	// being walked, and whether this pull carried an incremental window.
	depLanded := newLandedIDs()
	// PATCH(sync-since-last-modified): see the flat walker; one value, read by
	// the result-count recording today and by issue #17's deletion pass next.
	depWindowedPull := newSyncPullWindow(depSinceParam, depSinceTS, userParams, dep.Name, true)
	// PATCH(sync-watermark): a default run windows each parent from its own
	// watermark, so "was this pull windowed" is answered per parent and summed
	// here: the result count recorded for the resource is mirror-wide, and one
	// windowed parent already makes the sum describe less than the collection
	// (issue #22).
	depAnyParentWindowed := false
	depWatermarkStamp := syncWatermarkStamp(started)
	depWatermarkMayAdvance := syncWatermarkMayAdvance(dep.Name, sinceTS, userParams)
	parentFKKey := dep.ParentTable + "_id"

	for idx, parentRow := range parentRows {
		parentID := parentRow["id"]
		if parentID == "" {
			parentID = parentRow[pathParams[0].Field]
		}
		parentIDJSON, _ := json.Marshal(parentID)
		path := dep.PathTemplate
		for _, pathParam := range pathParams {
			path = replacePathParam(path, pathParam.Param, parentRow[pathParam.Field])
		}

		if humanFriendly {
			fmt.Fprintf(os.Stderr, "\r  %s: syncing for %s (%d/%d parents)", dep.Name, dep.ParentTable, idx+1, len(parentRows))
		}

		cursor := ""
		pagesFetched := 0
		lastNextCursor := ""
		// PATCH(pagination-headers): per-(company, resource) row count and
		// early-exit flag for the completeness check after this parent's walk.
		pageSink.Reset()
		depLanded.Reset() // PATCH(pagination-headers)
		parentTruncated := false
		// PATCH(sync-watermark): this parent's own window (issue #22). On the
		// default path it comes from the (company, resource) watermark; with
		// --since or --full, or for an endpoint with no temporal filter, it is
		// the resource-wide value computed above. A pair with no watermark gets
		// no window and is pulled in full — that is the first run.
		parentPull := depWindowedPull
		if mark := syncWatermarkWindow(db, parentID, dep.Name, sinceTS, full); mark != "" {
			parentPull = newSyncPullWindow(depSinceParam, mark, userParams, dep.Name, true)
			emitSyncWindow(syncEvents, dep.Name, parentID, mark)
		}
		// PATCH(sync-watermark): the scope-wide clear in RunE already dropped
		// this pair's mark before the first request; this covers a parent row
		// that only appeared after it (this run's own companies pull can add
		// one). A clear that fails leaves the old mark standing, so this pair
		// may not record a new one either.
		parentWatermarkBlocked := false
		if full {
			// The old mark cannot survive the refetch it is about to be
			// replaced by: an interrupted --full must leave "pull me in full".
			if !syncClearWatermark(db, syncEvents, parentID, dep.Name) {
				parentWatermarkBlocked = true
			}
		}
		if parentPull.Windowed {
			depAnyParentWindowed = true
		}
		// PATCH(sync-watermark): any failure this parent hit, including the
		// access denial that is deliberately NOT counted as truncation for the
		// result-count arithmetic. A watermark may only move over a pull that
		// had none.
		parentFailed := false
		// PATCH(sync-watermark): rows this walk fetched and then dropped —
		// all_items_failed_id_extraction and primary_key_unresolved. The walk
		// itself was not truncated, so the flag is its own: those rows did not
		// land, and nothing will fetch them again if the mark moves past them.
		// Without Fiken-Api-Result-Count there is no mismatch to catch it.
		parentRowsDropped := false

		for {
			params := map[string]string{}
			if resourceSupportsPagination(dep.Name) {
				params[pageSize.limitParam] = strconv.Itoa(pageSize.limit)
				if cursor != "" {
					params[pageSize.cursorParam] = cursor
				}
			}
			// PATCH(sync-since-last-modified): from the walk's window value.
			// PATCH(sync-watermark): which is this parent's, because the
			// watermark is per (company, resource) (issue #22).
			if parentPull.Value != "" {
				params[parentPull.Param] = parentPull.Value
			}
			// Apply user flags last so they win over spec-derived cursor/since/limit.
			// Dependent path: --param is skipped (already scoped by the parent path
			// segment); --global-param and --resource-param still apply.
			userParams.applyTo(dep.Name, params, true)

			data, err := c.Get(ctx, path, params)
			if err != nil {
				// Non-fatal per parent: log and continue to next parent.
				// Track access-denial separately so an all-denied dependent
				// resource can surface as a Warn rather than silent success.
				parentFailed = true // PATCH(sync-watermark)
				parentAccessDenied := false
				if w, ok := isSyncAccessWarning(err); ok {
					deniedParents++
					parentAccessDenied = true
					if firstDenial == nil {
						firstDenial = w
					}
					if humanFriendly {
						fmt.Fprintf(os.Stderr, "\n  %s: access denied for parent %s: %s\n", dep.Name, parentID, w.Reason)
					} else {
						fmt.Fprintln(syncEvents, syncWarningJSON(dep.Name, parentID, w.Status, w.Reason, w.Message))
					}
				} else if humanFriendly {
					fmt.Fprintf(os.Stderr, "\n  %s: error for parent %s: %v\n", dep.Name, parentID, err)
				} else {
					// Non-warning failures were previously silent in JSON mode —
					// operators only saw the missing rows. Emit a structured
					// sync_error so the API body and status are inspectable.
					fmt.Fprintln(syncEvents, syncErrorJSON(dep.Name, parentID, err))
				}
				// PATCH(pagination-headers): a parent that denied access before
				// serving a page landed no rows and contributes nothing to the
				// collection total, so it is walked-with-zero rather than a
				// truncated walk. One 403 company (a Fiken book without the API
				// module) otherwise blocked the recorded result_count for every
				// dependent resource of the whole mirror (issue #15). The zero
				// only matches what total_count counts for that company while
				// the mirror holds no rows for it; a company whose API module
				// lapsed after an earlier sync still has rows, and counting it
				// as zero would record a total short by exactly those rows.
				// Such a parent is neither counted nor treated as truncation:
				// it simply leaves this run unable to account for every parent,
				// so nothing is recorded.
				if parentAccessDenied && pagesFetched == 0 {
					if deniedParentIsAccountedFor(db, dep.Name, parentID) {
						depParentsDeniedAndEmpty++
					}
				} else {
					parentTruncated = true
				}
				break
			}

			items, nextCursor, hasMore := extractPageItems(data, pageSize.cursorParam)

			// Page-int paginator fallback: mirrors syncResource so dependent
			// resources on integer ?page=N APIs also advance past page 1.
			// Guard on cursorType to cover every canonical spelling.
			// PATCH(pagination-zero-based): the first request omits the cursor, so
			// the server served pageSize.firstPage (the spec's default for the page
			// parameter, 0 here). Atoi("") clamped to 1 and asked for page 2 next,
			// so page 1 was never fetched (issue #12). Empty cursor means firstPage;
			// the next page is current+1, and a short page ends the loop below.
			if pageSize.cursorType == "page" && nextCursor == "" && len(items) >= pageSize.limit && pageAllowsPageIntFallback(data) {
				currentPage := pageSize.firstPage
				if n, err := strconv.Atoi(cursor); err == nil {
					currentPage = n
				}
				nextCursor = strconv.Itoa(currentPage + 1)
				hasMore = true
			}
			if pageSize.cursorType == "offset" && nextCursor == "" && len(items) >= pageSize.limit && pageAllowsPageIntFallback(data) {
				currentOffset, _ := strconv.Atoi(cursor)
				nextCursor = strconv.Itoa(currentOffset + pageSize.limit)
				hasMore = true
			}

			if len(items) == 0 && len(data) > 0 && !isJSONResponse(data) {
				if humanFriendly {
					fmt.Fprintf(os.Stderr, "\nwarning: %s returned a 200 response with a non-JSON body for parent %s; no rows were stored.\n", dep.Name, parentID)
				} else {
					fmt.Fprintf(syncEvents, `{"event":"sync_anomaly","resource":"%s","parent":"%s","reason":"non_json_200_body"}`+"\n", dep.Name, parentID)
				}
				parentTruncated = true // PATCH(pagination-headers)
				break
			}

			if len(items) == 0 {
				// PATCH(sync-full-deletes): only a body that really IS an empty
				// collection may end this walk comparably. The flat walker has
				// tested isEmptyPageResponse here since it was printed (:663);
				// this one broke on ANY zero-item body — a bare object, `null`,
				// an unrecognised envelope — and left parentTruncated false with
				// an empty landed set. Beside a Fiken-Api-Result-Count of 0 that
				// reads as "the collection is empty and the walk saw all of it",
				// and the deletion pass then takes every row of that (company,
				// resource). A body this walker could not read is exactly the
				// case where an absent row proves nothing (issue #17).
				if !isEmptyPageResponse(data) {
					parentTruncated = true
				}
				break
			}

			for i, item := range items {
				var obj map[string]json.RawMessage
				if err := json.Unmarshal(item, &obj); err == nil {
					obj["parent_id"] = parentIDJSON
					if _, ok := obj[parentFKKey]; !ok {
						obj[parentFKKey] = parentIDJSON
					}
					for _, pathParam := range pathParams {
						if pathParam.Field == "id" {
							continue
						}
						if _, ok := obj[pathParam.Field]; ok {
							continue
						}
						valueJSON, _ := json.Marshal(parentRow[pathParam.Field])
						obj[pathParam.Field] = valueJSON
					}
					if modified, err := json.Marshal(obj); err == nil {
						items[i] = modified
					}
				}
			}

			stored, extractFailures, err := upsertResourceBatch(db, dep.Name, items)
			if err != nil {
				if humanFriendly {
					fmt.Fprintf(os.Stderr, "\n  %s: upsert error for parent %s: %v\n", dep.Name, parentID, err)
				}
				parentTruncated = true // PATCH(pagination-headers)
				break
			}

			depLanded.addBatch(dep.Name, items) // PATCH(pagination-headers)
			depConsumedTotal += len(items)
			depExtractFailureTotal += extractFailures
			// PATCH(sync-watermark): recorded outside the emit gate below —
			// only the FIRST anomaly of a resource is reported, but every one
			// of them dropped rows from this parent's pull.
			if stored < len(items) {
				parentRowsDropped = true
			}
			// Order matches the flat path (syncResource): all-fail first,
			// then partial-fail. The all-fail case dominates — if stored==0
			// with at least one item, the resource is broken regardless of
			// how many extractions failed individually.
			if len(items) > 0 && stored == 0 && !depAnomalyEmitted {
				if humanFriendly {
					fmt.Fprintf(os.Stderr, "\nwarning: %s returned %d items for parent %s but stored 0 — likely scalar item shape or unrecognized primary-key field name.\n", dep.Name, len(items), parentID)
				} else {
					fmt.Fprintf(syncEvents, `{"event":"sync_anomaly","resource":"%s","parent":"%s","consumed":%d,"stored":0,"reason":"all_items_failed_id_extraction"}`+"\n", dep.Name, parentID, len(items))
				}
				depAnomalyEmitted = true
			} else if extractFailures > 0 && stored > 0 && !depAnomalyEmitted {
				if humanFriendly {
					fmt.Fprintf(os.Stderr, "\nwarning: %s had %d item(s) with no extractable primary key — those rows were dropped silently. Annotate the spec with x-resource-id to fix.\n", dep.Name, extractFailures)
				} else {
					fmt.Fprintf(syncEvents, `{"event":"sync_anomaly","resource":"%s","parent":"%s","consumed":%d,"stored":%d,"count":%d,"reason":"primary_key_unresolved"}`+"\n", dep.Name, parentID, len(items), stored, extractFailures)
				}
				depAnomalyEmitted = true
			}

			totalCount += stored
			if resourceSupportsPagination(dep.Name) && nextCursor == "" && pageSize.cursorParam != "offset" && len(items) >= pageSize.limit && pageMayHaveMore(data) {
				emitSyncMissingPaginationCursorWarning(syncEvents, humanFriendly, dep.Name, parentID)
				// PATCH(sync-watermark): a full page the API says has more
				// behind it, and no cursor to reach it with, is a prefix of the
				// collection. Whether the loop then stops here depends on
				// determinePaginationDefaults' cursor type; the completeness of
				// the pull must not (issue #22).
				parentTruncated = true
			}
			pagesFetched++

			if maxPages > 0 && pagesFetched >= maxPages {
				parentTruncated = true // PATCH(pagination-headers)
				if !latestOnly {
					if humanFriendly {
						fmt.Fprintf(os.Stderr, "\n  %s: reached --max-pages limit (%d pages, %d items) for parent %s\n", dep.Name, maxPages, totalCount, parentID)
					} else {
						fmt.Fprintf(syncEvents, `{"event":"sync_warning","resource":"%s","parent":"%s","reason":"max_pages_cap_hit","message":"reached --max-pages cap of %d; data may be truncated. Re-run with --max-pages 0 (unlimited) or higher to verify."}`+"\n", dep.Name, parentID, maxPages)
					}
				}
				break
			}
			// Sticky-cursor detector: see syncResource for rationale. Same shape
			// here so dependent-resource page loops cannot burn the budget on a
			// non-advancing next cursor.
			if nextCursor != "" && nextCursor == lastNextCursor {
				if humanFriendly {
					fmt.Fprintf(os.Stderr, "\n  %s: API returned the same next cursor across two pages for parent %s; aborting to prevent budget waste.\n", dep.Name, parentID)
				} else {
					fmt.Fprintf(syncEvents, `{"event":"sync_warning","resource":"%s","parent":"%s","reason":"stuck_pagination","message":"API returned the same next cursor across two pages for resource %s; aborting to prevent budget waste."}`+"\n", dep.Name, parentID, dep.Name)
				}
				parentTruncated = true // PATCH(pagination-headers)
				break
			}
			lastNextCursor = nextCursor
			if !resourceSupportsPagination(dep.Name) {
				break
			}
			if !hasMore || len(items) < pageSize.limit {
				break
			}
			if nextCursor == "" {
				if pageSize.cursorType == "offset" {
					// Cursor-based APIs return the next cursor in the envelope.
					// Offset-based APIs carry their pagination position client-side.
					currentOffset, _ := strconv.Atoi(cursor)
					nextCursor = strconv.Itoa(currentOffset + pageSize.limit)
				} else {
					// A cursor-based API reporting has_more without a next cursor
					// cannot advance safely; stop instead of looping silently.
					// PATCH(sync-watermark): and say that the walk stopped short
					// of the collection, so the watermark cannot move past the
					// pages this cursor never reached (issue #22).
					parentTruncated = true
					break
				}
			}
			cursor = nextCursor
		}

		// PATCH(pagination-headers): compare what this company's collection was
		// said to hold against what landed for it (issue #15). parentID is the
		// company slug: every dependent here hangs off the companies table.
		parentPageInfo := pageSink.PageInfo()
		parentCountMismatch := false // PATCH(sync-watermark)
		if parentPageInfo.HasResultCount {
			depParentsWithResultCount++
			depResultCountTotal += parentPageInfo.ResultCount
			if !parentTruncated && depLanded.Len() != parentPageInfo.ResultCount {
				parentCountMismatch = true
				emitResultCountMismatch(syncEvents, dep.Name, parentID, parentPageInfo.ResultCount, depLanded.Len())
			}
		}
		// PATCH(sync-watermark): the pull is now on record as complete or not,
		// which is the last input the watermark needs (issue #22). Everything
		// this run asked Fiken for landed for this (company, resource): no
		// transport or access error, no truncation (cap, stuck cursor, upsert
		// failure, unreadable body, a full page with no cursor behind it), no
		// row fetched and then dropped for want of a primary key, a --full
		// clear that actually cleared, and — where the API said how many rows
		// the window held — exactly that many distinct rows. Anything less
		// leaves the watermark alone and costs one more full pull next time,
		// which is the only direction that cannot lose a row.
		if depWatermarkMayAdvance && !parentFailed && !parentTruncated && !parentCountMismatch && !parentRowsDropped && !parentWatermarkBlocked {
			syncAdvanceWatermark(db, parentID, dep.Name, depWatermarkStamp)
		}
		// PATCH(sync-full-deletes): the mirror had no way to lose a row Fiken
		// deleted (issue #17). A complete, unwindowed, untruncated pull of this
		// company's collection — proven complete by the count check just above —
		// is the only thing that makes an absent row evidence of a deletion, so
		// the sweep is here, per parent, and consults all three of them.
		// PATCH(sync-watermark): with this parent's window, not the resource's:
		// a pull windowed from the watermark saw only what changed, so every
		// unchanged row is absent by construction and none of them is deleted.
		syncPruneDeletedRows(db, syncEvents, dep.Name, parentID, depLanded, parentPageInfo, parentTruncated, parentPull)
		if parentTruncated {
			depWalkTruncated = true
		}

		// Brief rate-limit pause between parents to avoid hammering the API
		time.Sleep(100 * time.Millisecond)
	}

	if humanFriendly {
		fmt.Fprintf(os.Stderr, "\n")
	}

	// PATCH(mirror-canonical-resource-name): persist the real row count (issue #6 §3).
	_ = db.SaveSyncState(dep.Name, "", syncStateTotalCount(db, dep.Name, totalCount))
	// PATCH(pagination-headers): only a run that walked every parent to the end,
	// with each one either carrying the header or denying access before serving
	// a page while holding no rows in the mirror, produces a number on the same
	// scale as total_count, which is mirror-wide (issue #15).
	// PATCH(sync-watermark): windowedness is per parent now, so the run counts
	// as windowed when ANY parent was — the sum is then short of the collection
	// by whatever the other parents did not change (issue #22).
	recordSyncResultCount(db, dep.Name, depResultCountTotal, shouldRecordResultCount(everyParentAccountedFor(depParentsWithResultCount, depParentsDeniedAndEmpty, len(parentRows)), depWalkTruncated, depWindowedPull.Windowed || depAnyParentWindowed))

	// F4b symptom probe: items consumed and extracted but nothing landed.
	// See syncResource for rationale.
	if depConsumedTotal > 0 && totalCount == 0 && depExtractFailureTotal < depConsumedTotal {
		if humanFriendly {
			fmt.Fprintf(os.Stderr, "\nwarning: %s consumed %d items, extracted %d primary keys, but stored 0 rows — extraction succeeded yet nothing landed. Investigate FTS triggers / transaction rollback / encoding.\n", dep.Name, depConsumedTotal, depConsumedTotal-depExtractFailureTotal)
		} else {
			fmt.Fprintf(syncEvents, `{"event":"sync_anomaly","resource":"%s","consumed":%d,"stored":0,"extract_failures":%d,"reason":"stored_count_zero_after_extraction"}`+"\n", dep.Name, depConsumedTotal, depExtractFailureTotal)
		}
	}

	// If every parent was access-denied and nothing was synced, surface as a
	// warning so the run-level summary and exit code reflect insufficient access.
	if deniedParents == len(parentRows) && totalCount == 0 && firstDenial != nil {
		return syncResult{
			Resource: dep.Name,
			Count:    0,
			Warn:     fmt.Errorf("skipped %s: %s on all %d parents", dep.Name, firstDenial.Reason, len(parentRows)),
			Duration: time.Since(started),
		}
	}
	return syncResult{Resource: dep.Name, Count: totalCount, Duration: time.Since(started)}
}

func dependentParentFields(pathParams []dependentPathParamDef) []string {
	fields := []string{"id"}
	seen := map[string]bool{"id": true}
	for _, pathParam := range pathParams {
		if pathParam.Field == "" || seen[pathParam.Field] {
			continue
		}
		fields = append(fields, pathParam.Field)
		seen[pathParam.Field] = true
	}
	return fields
}

func dependentParentRows(db *store.Store, parentTable string, pathParams []dependentPathParamDef) ([]map[string]string, error) {
	fields := dependentParentFields(pathParams)
	if len(fields) == 1 {
		values, err := db.ListIDs(parentTable)
		if err != nil {
			return nil, err
		}
		rows := make([]map[string]string, 0, len(values))
		for _, value := range values {
			rows = append(rows, map[string]string{"id": value})
		}
		return rows, nil
	}
	if len(pathParams) == 1 && len(fields) == 2 && fields[0] == "id" {
		values, err := db.ListField(parentTable, fields[1])
		if err != nil {
			return nil, err
		}
		rows := make([]map[string]string, 0, len(values))
		for _, value := range values {
			rows = append(rows, map[string]string{"id": value, fields[1]: value})
		}
		return rows, nil
	}
	return db.ListFieldSets(parentTable, fields)
}

// resourceIDFieldOverrides projects per-resource IDField (set by the profiler
// from x-resource-id or the response-schema fallback chain) into a runtime
// lookup map. extractID consults this first so the templated path wins over
// the generic fallback list; the generic list applies only when the override
// is empty or the override field is absent on a given item.
//
// Includes both flat resources and dependent (parent-child) resources so
// annotations on a child path-item are honored at runtime, not just on
// flat paths.
var resourceIDFieldOverrides = map[string]string{
	// PATCH(mirror-id-keys-accounts-inbox): key on the account code, not the
	// display name (issue #16).
	"accounts":      "code",
	"bank_accounts": "bankAccountId",
	"companies":     "slug",
	"contacts":      "contactId",
	// PATCH(sync-invoices-creditnotes): invoiceResult (spec.yaml:5759) carries
	// invoiceId as a plain readOnly property (:5762, no required block) and
	// creditNoteResult requires creditNoteId (spec.yaml:4930); neither name is
	// in genericIDFieldFallbacks, so without these two entries every row of the
	// new resources is an extract failure (issue #18).
	"credit_notes": "creditNoteId",
	"invoices":     "invoiceId",
	// PATCH(mirror-id-keys-accounts-inbox): key on documentId, the path id of
	// getInboxDocument, not the display name (issue #16).
	"inbox":           "documentId",
	"journal_entries": "journalEntryId",
	"products":        "productId",
	"projects":        "projectId",
	"purchases":       "purchaseId",
	"sales":           "saleId",
	"transactions":    "transactionId",
}

// genericIDFieldFallbacks is the runtime safety net for resources that did
// NOT receive a templated IDField. API-specific names belong in spec
// annotations (x-resource-id), not this list. Order matters: vendor
// identifier names (gid, sid, uid, uuid, guid) take precedence over `name`
// so APIs like Asana (gid) and Twilio (sid) don't fall through to a display
// field and upsert on names — see #1394.
var genericIDFieldFallbacks = []string{"id", "ID", "gid", "sid", "uid", "uuid", "guid", "name", "slug", "key", "code"}

// pageItemKeys is scanned in priority order; lowercase REST-convention keys
// come first, PascalCase .NET variants second. Without the PascalCase row,
// {"Items": [...]} envelopes fall through to the ambiguity scan and a
// single-array sibling miscount silently truncates sync.
var pageItemKeys = []string{
	"data", "results", "items", "records", "nodes", "entries", "features",
	"Data", "Results", "Items", "Records", "Nodes", "Entries", "Features",
}

var dataEnvelopeKeys = []string{"data", "Data", "result", "Result"}

var pageMetadataArrayKeys = map[string]bool{
	"errors": true, "Errors": true,
	"warnings": true, "Warnings": true,
}

var pageEnvelopeMetadataKeys = map[string]bool{
	// list wrappers themselves
	"data": true, "results": true, "items": true,
	"Data": true, "Results": true, "Items": true,
	// pagination cursors / tokens
	"next_cursor": true, "nextCursor": true, "NextCursor": true,
	"next_token": true, "nextToken": true, "NextToken": true,
	"next_page_token": true, "nextPageToken": true, "NextPageToken": true,
	"page_token": true, "pageToken": true, "PageToken": true,
	"end_cursor": true, "endCursor": true, "EndCursor": true,
	"start_cursor": true, "startCursor": true, "StartCursor": true,
	"cursor": true, "Cursor": true, "after": true, "After": true, "before": true, "Before": true,
	// has-more flags and page numbers
	"has_more": true, "hasMore": true, "HasMore": true,
	"has_next": true, "hasNext": true, "HasNext": true,
	"next_page": true, "nextPage": true, "NextPage": true,
	"previous_page": true, "previousPage": true, "PreviousPage": true,
	"page": true, "Page": true, "page_size": true, "pageSize": true, "PageSize": true,
	"per_page": true, "perPage": true, "PerPage": true,
	// counts / totals
	"total": true, "Total": true, "count": true, "Count": true, "size": true, "Size": true,
	"total_count": true, "totalCount": true, "TotalCount": true,
	// JSend / common status envelopes
	"success": true, "status": true, "message": true, "error": true, "errors": true,
	"warnings": true, "Warnings": true, "ok": true, "Ok": true,
	// wrapper objects
	"links": true, "meta": true, "pagination": true,
	"response_metadata": true, "paging": true,
	// links shape
	"next": true, "prev": true, "previous": true, "first": true, "last": true,
}

// criticalResources is the template-time projection of per-resource Critical
// (set by the profiler from the spec's path-item x-critical extension). It
// is consulted at error-aggregation time so a non-critical failure can be
// downgraded to a sync_warning + exit 0 unless --strict was passed.
//
// Includes both flat resources and dependent (parent-child) resources so a
// failed child sync flagged x-critical: true exits non-zero just like a
// flat-resource critical failure.
var criticalResources = map[string]bool{}

// extractID resolves an item's primary-key field. It consults the
// per-resource templated override first; on miss, it falls through to the
// generic fallback list. resource may be empty for callers that don't have
// a resource context (only the generic list applies in that case).
//
// Field lookups go through store.LookupFieldValue so snake_case overrides
// match camelCase JSON renderings. UpsertBatch resolves fields the same
// way — divergence between the two paths produces silent drops on
// heterogeneous payloads.
func extractID(resource string, obj map[string]any) string {
	if override, ok := resourceIDFieldOverrides[resource]; ok && override != "" {
		if v := store.LookupFieldValue(obj, override); v != nil {
			s := store.ResourceIDString(v)
			if s != "" && s != "<nil>" {
				return s
			}
		}
	}
	for _, key := range genericIDFieldFallbacks {
		if v := store.LookupFieldValue(obj, key); v != nil {
			s := store.ResourceIDString(v)
			if s != "" && s != "<nil>" {
				return s
			}
		}
	}
	if s := suffixIDFieldFallback(resource, obj); s != "" {
		return s
	}
	return ""
}

// suffixIDFieldFallback resolves an id-less resource that keys on its own
// "<name>_code" / "<name>_id" / "<name>_key" / "<name>_slug" field (e.g. the
// "currencies" resource keying on "currency_code" — see #2327). It is scoped to
// the resource's OWN name so a foreign key like account_id/parent_id is never
// promoted to the primary key, and it uses direct map lookups in a fixed suffix
// order so the chosen id is deterministic.
func suffixIDFieldFallback(resourceType string, obj map[string]any) string {
	for _, base := range resourceIDBaseNames(resourceType) {
		for _, suffix := range []string{"_id", "_code", "_key", "_slug"} {
			if v, ok := obj[base+suffix]; ok {
				if s := scalarIDString(v); s != "" && s != "<nil>" {
					return s
				}
			}
		}
	}
	return ""
}

// resourceIDBaseNames returns lowercase candidate singular/plural stems of a
// resource name to build "<base>_id"-style key probes from (e.g. "currencies"
// -> ["currencies","currency"]). OpenAPI-/path-derived names can carry a
// leading verb token ("get-currencies"), so the same probes are also attempted
// on the de-verbed stem. Minimal English depluralization; the raw name is
// always included so already-singular names work too.
func resourceIDBaseNames(resourceType string) []string {
	r := strings.ToLower(strings.TrimSpace(resourceType))
	if r == "" {
		return nil
	}
	stems := []string{r}
	if d := stripLeadingResourceVerb(r); d != "" && d != r {
		stems = append(stems, d)
	}
	var bases []string
	seen := map[string]bool{}
	add := func(s string) {
		if s != "" && !seen[s] {
			seen[s] = true
			bases = append(bases, s)
		}
	}
	for _, stem := range stems {
		add(stem)
		add(depluralizeResourceStem(stem))
	}
	return bases
}

func stripLeadingResourceVerb(r string) string {
	for _, verb := range []string{"get", "list", "fetch", "find", "retrieve", "read", "show", "all"} {
		for _, sep := range []string{"-", "_"} {
			prefix := verb + sep
			if strings.HasPrefix(r, prefix) && len(r) > len(prefix) {
				return r[len(prefix):]
			}
		}
	}
	return ""
}

func depluralizeResourceStem(r string) string {
	switch {
	case strings.HasSuffix(r, "ies") && len(r) > 3:
		return strings.TrimSuffix(r, "ies") + "y" // currencies -> currency
	// Plurals formed by adding "es" to a base ending in s/x/z/ch/sh. The
	// double-s "sses" guard (not bare "ses") keeps soft-e plurals — where the
	// singular already ends in a silent "e" (cases, databases, licenses,
	// purchases) — out of this branch; they fall through to the "-s" case below
	// (cases -> case, not cas). Trade-off: a genuine "-es" plural of an s-ending
	// singular (buses, statuses) depluralizes imperfectly, but those are rare as
	// resource names and this stem only feeds best-effort id-field probing.
	case strings.HasSuffix(r, "sses") || strings.HasSuffix(r, "xes") ||
		strings.HasSuffix(r, "zes") || strings.HasSuffix(r, "ches") ||
		strings.HasSuffix(r, "shes"):
		return strings.TrimSuffix(r, "es") // classes -> class, boxes -> box, dishes -> dish
	case strings.HasSuffix(r, "s") && !strings.HasSuffix(r, "ss") && len(r) > 1:
		return strings.TrimSuffix(r, "s") // languages -> language, cases -> case
	}
	return r
}

func scalarIDString(value any) string {
	switch value.(type) {
	case string, bool, int, int8, int16, int32, int64,
		uint, uint8, uint16, uint32, uint64,
		float32, float64, json.Number, []byte:
		return store.ResourceIDString(value)
	default:
		return ""
	}
}
